INSERT INTO "stories" ("slug", "fund_id", "status", "is_featured", "is_sample", "published_on", "content") VALUES ('dorm-cookout', 'morale', 'published', true, true, '2026-09-14', '{"en":{"title":"The cookout that made the dorms feel like home","name":"Jaylen","role":"Airman First Class, aircraft maintenance","summary":"Three months into his first assignment, Jaylen hadn''t met anyone outside his shop. A dorm cookout paid for by the morale fund changed that.","quote":"I knew the people I worked with. After that night, I knew my neighbors.","body":"<p>Jaylen arrived at his first base straight out of technical school. He worked long shifts on the flight line, went back to the dorms, and did it again the next day. Three months in, he knew his shop and almost nobody else.</p><p>When another Airman suggested a cookout behind the dorms, members voted it through at the next meeting. The morale fund paid for the food, the grills and a few yard games.</p><h2>One evening, a lot of new names</h2><p>Dozens of Airmen came out. Jaylen ended up running a grill next to two Airmen from a squadron he''d never worked with, and they''re still the people he calls on a weekend.</p><blockquote><p>I knew the people I worked with. After that night, I knew my neighbors.</p></blockquote><p>Now he helps plan the next one, and he makes a point of knocking on the door of whoever just moved in.</p><p>Gifts to the morale and events fund pay for the cookouts, game nights and trips that bring Airmen together.</p>"},"es":{"title":"La parrillada que convirtió las residencias en un hogar","name":"Jaylen","role":"Aviador de primera clase, mantenimiento de aeronaves","summary":"A tres meses de su primer destino, Jaylen no conocía a nadie fuera de su taller. Una parrillada pagada por el fondo de moral cambió eso.","quote":"Conocía a la gente con la que trabajaba. Después de esa noche, conocía a mis vecinos.","body":"<p>Jaylen llegó a su primera base recién salido de la escuela técnica. Hacía turnos largos en la línea de vuelo, volvía a la residencia y al día siguiente repetía. A los tres meses conocía a su taller y a casi nadie más.</p><p>Cuando otro aviador propuso una parrillada detrás de las residencias, los miembros la aprobaron en la siguiente reunión. El fondo de moral pagó la comida, las parrillas y algunos juegos al aire libre.</p><h2>Una tarde, muchos nombres nuevos</h2><p>Vinieron decenas de aviadores. Jaylen terminó a cargo de una parrilla junto a dos aviadores de un escuadrón con el que nunca había trabajado, y hoy siguen siendo la gente a la que llama los fines de semana.</p><blockquote><p>Conocía a la gente con la que trabajaba. Después de esa noche, conocía a mis vecinos.</p></blockquote><p>Ahora ayuda a planear la próxima, y siempre llama a la puerta de quien acaba de mudarse.</p><p>Las donaciones al fondo de moral y eventos pagan las parrilladas, noches de juegos y salidas que unen a los aviadores.</p>"},"fr":{"title":"Le barbecue qui a fait des dortoirs un vrai chez-soi","name":"Jaylen","role":"Aviateur de première classe, maintenance aéronautique","summary":"Trois mois après le début de sa première affectation, Jaylen ne connaissait personne en dehors de son atelier. Un barbecue financé par le fonds moral a tout changé.","quote":"Je connaissais mes collègues. Après cette soirée, je connaissais mes voisins.","body":"<p>Jaylen est arrivé sur sa première base tout juste sorti de l''école technique. Il enchaînait de longues journées sur la ligne de vol, rentrait au dortoir et recommençait le lendemain. Au bout de trois mois, il connaissait son atelier et presque personne d''autre.</p><p>Quand un autre aviateur a proposé un barbecue derrière les dortoirs, les membres l''ont voté à la réunion suivante. Le fonds moral a payé la nourriture, les barbecues et quelques jeux de plein air.</p><h2>Une soirée, beaucoup de nouveaux noms</h2><p>Des dizaines d''aviateurs sont venus. Jaylen s''est retrouvé derrière un barbecue avec deux aviateurs d''un escadron avec lequel il n''avait jamais travaillé, et ce sont encore eux qu''il appelle le week-end.</p><blockquote><p>Je connaissais mes collègues. Après cette soirée, je connaissais mes voisins.</p></blockquote><p>Aujourd''hui, il aide à organiser le prochain, et il frappe toujours à la porte des nouveaux arrivants.</p><p>Les dons au fonds moral et événements financent les barbecues, soirées jeux et sorties qui rapprochent les aviateurs.</p>"}}'::jsonb) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "stories" ("slug", "fund_id", "status", "is_featured", "is_sample", "published_on", "content") VALUES ('study-hall', 'development', 'published', false, true, '2026-08-03', '{"en":{"title":"A study group and a room full of mentors","name":"Keisha","role":"Senior Airman, personnel","summary":"Keisha started a weekly study group for Airmen preparing for promotion testing. The professional growth fund paid for the books, and senior NCOs came to help.","quote":"Leading the group taught me as much as the books did.","body":"<p>Keisha was studying for promotion testing on her own, late at night, from secondhand notes. She guessed she wasn''t the only one.</p><p>She brought the idea of a weekly study group to a meeting. Members backed it, and the professional growth fund bought a set of study guides the group could share.</p><h2>Learning to lead</h2><p>Running the group meant booking a room, keeping eight to ten Airmen on track, and asking for help when the material got tough. Two senior NCOs from her squadron started dropping by to answer questions and talk about how they''d prepared.</p><blockquote><p>Leading the group taught me as much as the books did.</p></blockquote><p>The group still meets, and the books get passed on from one testing cycle to the next.</p><p>Gifts to the professional growth fund help junior Airmen build leadership skills early in their careers.</p>"},"es":{"title":"Un grupo de estudio y una sala llena de mentores","name":"Keisha","role":"Aviadora sénior, personal","summary":"Keisha organizó un grupo de estudio semanal para aviadores que preparaban sus exámenes de ascenso. El fondo de crecimiento profesional pagó los libros y suboficiales con experiencia vinieron a ayudar.","quote":"Dirigir el grupo me enseñó tanto como los libros.","body":"<p>Keisha estudiaba sola para sus exámenes de ascenso, tarde por la noche y con apuntes de segunda mano. Supuso que no era la única.</p><p>Llevó a una reunión la idea de un grupo de estudio semanal. Los miembros la apoyaron, y el fondo de crecimiento profesional compró un juego de guías de estudio para que el grupo las compartiera.</p><h2>Aprender a liderar</h2><p>Dirigir el grupo significaba reservar una sala, mantener al día a entre ocho y diez aviadores y pedir ayuda cuando el material se complicaba. Dos suboficiales con experiencia de su escuadrón empezaron a pasar para resolver dudas y contar cómo se habían preparado.</p><blockquote><p>Dirigir el grupo me enseñó tanto como los libros.</p></blockquote><p>El grupo sigue reuniéndose, y los libros pasan de un ciclo de exámenes al siguiente.</p><p>Las donaciones al fondo de crecimiento profesional ayudan a los aviadores jóvenes a desarrollar su liderazgo desde el inicio de su carrera.</p>"},"fr":{"title":"Un groupe d''étude et une salle pleine de mentors","name":"Keisha","role":"Aviatrice senior, ressources humaines","summary":"Keisha a lancé un groupe d''étude hebdomadaire pour les aviateurs qui préparaient leurs examens d''avancement. Le fonds de développement professionnel a payé les livres, et des sous-officiers expérimentés sont venus aider.","quote":"Animer le groupe m''a appris autant que les livres.","body":"<p>Keisha révisait seule ses examens d''avancement, tard le soir, avec des notes de seconde main. Elle se doutait qu''elle n''était pas la seule.</p><p>Elle a proposé en réunion de créer un groupe d''étude hebdomadaire. Les membres ont soutenu l''idée, et le fonds de développement professionnel a acheté une série de guides que le groupe pouvait se partager.</p><h2>Apprendre à diriger</h2><p>Animer le groupe, c''était réserver une salle, garder huit à dix aviateurs sur les rails et demander de l''aide quand la matière devenait difficile. Deux sous-officiers expérimentés de son escadron ont commencé à passer pour répondre aux questions et raconter comment ils s''étaient préparés.</p><blockquote><p>Animer le groupe m''a appris autant que les livres.</p></blockquote><p>Le groupe se réunit toujours, et les livres passent d''une session d''examens à la suivante.</p><p>Les dons au fonds de développement professionnel aident les jeunes aviateurs à développer leur leadership dès le début de leur carrière.</p>"}}'::jsonb) ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
INSERT INTO "stories" ("slug", "fund_id", "status", "is_featured", "is_sample", "published_on", "content") VALUES ('day-room-rebuild', 'community', 'published', false, true, '2026-06-21', '{"en":{"title":"Rebuilding the dorm day room","name":"Marcus","role":"Airman, security forces","summary":"Twenty Airmen spent two weekends turning a tired dorm day room into a space people actually use. The community fund bought the paint and furniture.","quote":"We walk past that room every day. Now it''s ours, because we built it.","body":"<p>The day room on the ground floor of Marcus''s dorm had peeling paint, a broken couch and a TV nobody could get working. Most Airmen walked straight past it.</p><p>At a meeting, Marcus asked whether the group could fix it up. Members agreed, worked out a budget and got the go-ahead from dorm leadership. The community fund paid for paint, new furniture and a few tools.</p><h2>Two weekends of work</h2><p>About twenty Airmen signed up. They patched walls, painted, put furniture together and hauled the old couch away. Someone brought a speaker, and someone else brought food.</p><blockquote><p>We walk past that room every day. Now it''s ours, because we built it.</p></blockquote><p>These days the room hosts study sessions, game nights and the occasional birthday.</p><p>Gifts to the community projects fund buy the supplies Airmen use to improve the base and the local community.</p>"},"es":{"title":"La renovación de la sala común","name":"Marcus","role":"Aviador, fuerzas de seguridad","summary":"Veinte aviadores pasaron dos fines de semana convirtiendo una sala común descuidada en un espacio que la gente usa de verdad. El fondo comunitario compró la pintura y los muebles.","quote":"Pasamos por esa sala todos los días. Ahora es nuestra, porque la construimos nosotros.","body":"<p>La sala común de la planta baja de la residencia de Marcus tenía la pintura descascarada, un sofá roto y un televisor que nadie lograba encender. La mayoría de los aviadores pasaba de largo.</p><p>En una reunión, Marcus preguntó si el grupo podía arreglarla. Los miembros aceptaron, definieron un presupuesto y obtuvieron el visto bueno de los responsables de la residencia. El fondo comunitario pagó la pintura, muebles nuevos y algunas herramientas.</p><h2>Dos fines de semana de trabajo</h2><p>Se apuntaron unos veinte aviadores. Repararon paredes, pintaron, armaron muebles y se llevaron el sofá viejo. Alguien trajo un altavoz y alguien más trajo comida.</p><blockquote><p>Pasamos por esa sala todos los días. Ahora es nuestra, porque la construimos nosotros.</p></blockquote><p>Hoy la sala acoge sesiones de estudio, noches de juegos y algún que otro cumpleaños.</p><p>Las donaciones al fondo de proyectos comunitarios compran los materiales que los aviadores usan para mejorar la base y la comunidad local.</p>"},"fr":{"title":"La rénovation de la salle commune","name":"Marcus","role":"Aviateur, forces de sécurité","summary":"Vingt aviateurs ont passé deux week-ends à transformer une salle commune défraîchie en un lieu que tout le monde utilise. Le fonds solidaire a acheté la peinture et le mobilier.","quote":"On passe devant cette salle tous les jours. Maintenant, elle est à nous, parce qu''on l''a construite.","body":"<p>La salle commune au rez-de-chaussée du dortoir de Marcus avait la peinture écaillée, un canapé cassé et une télévision que personne n''arrivait à faire marcher. La plupart des aviateurs passaient devant sans s''arrêter.</p><p>En réunion, Marcus a demandé si le groupe pouvait la remettre en état. Les membres ont accepté, établi un budget et obtenu le feu vert des responsables du dortoir. Le fonds solidaire a payé la peinture, de nouveaux meubles et quelques outils.</p><h2>Deux week-ends de travail</h2><p>Une vingtaine d''aviateurs se sont inscrits. Ils ont rebouché les murs, peint, monté les meubles et emporté le vieux canapé. Quelqu''un a apporté une enceinte, quelqu''un d''autre à manger.</p><blockquote><p>On passe devant cette salle tous les jours. Maintenant, elle est à nous, parce qu''on l''a construite.</p></blockquote><p>Aujourd''hui, la salle accueille des séances de révision, des soirées jeux et parfois un anniversaire.</p><p>Les dons au fonds des projets solidaires achètent le matériel que les aviateurs utilisent pour améliorer la base et la communauté locale.</p>"}}'::jsonb) ON CONFLICT ("slug") DO NOTHING;
